<div class="section-intro"><div><h2>Laporan operasional</h2><p>Semua angka berasal dari transaksi penjualan dan pembelian tersimpan.</p></div><a class="button button-outline" href="?page=dashboard">← Dashboard</a></div>
<form class="filter-bar" method="get"><input type="hidden" name="page" value="reports"><label>Dari tanggal<input type="date" name="from" value="<?= e($from) ?>" required></label><label>Sampai tanggal<input type="date" name="to" value="<?= e($to) ?>" required></label><button class="button button-outline" type="submit">Tampilkan laporan</button></form>
<?php $revenue = (float) $summary['revenue']; $margin = $revenue > 0 ? (float) $summary['gross_profit'] / $revenue * 100 : 0; ?>
<section class="stats-grid report-stats">
    <article class="stat-card"><span class="stat-icon green">↗</span><span class="stat-label">Omzet bersih</span><strong><?= rupiah($summary['revenue']) ?></strong><small><?= e(format_date($from)) ?> – <?= e(format_date($to)) ?></small></article>
    <article class="stat-card"><span class="stat-icon blue">▤</span><span class="stat-label">HPP penjualan</span><strong><?= rupiah($summary['cogs']) ?></strong><small>Biaya pada saat transaksi</small></article>
    <article class="stat-card"><span class="stat-icon yellow">◈</span><span class="stat-label">Laba kotor</span><strong><?= rupiah($summary['gross_profit']) ?></strong><small>Margin <?= number_format($margin, 1, ',', '.') ?>%</small></article>
    <article class="stat-card"><span class="stat-icon red">−</span><span class="stat-label">Biaya operasional</span><strong><?= rupiah($summary['expenses']) ?></strong><small>Biaya aktif di periode ini</small></article>
    <article class="stat-card"><span class="stat-icon green">✓</span><span class="stat-label">Laba bersih</span><strong><?= rupiah($summary['net_profit']) ?></strong><small>Laba kotor setelah biaya usaha</small></article>
    <article class="stat-card"><span class="stat-icon red">▣</span><span class="stat-label">Transaksi</span><strong><?= number_format((int) $summary['transactions'], 0, ',', '.') ?></strong><small>Transaksi terkonfirmasi</small></article>
</section>
<section class="panel table-panel"><div class="panel-heading"><div><h3>Performa harian</h3><p>Ringkasan omzet dan laba per tanggal.</p></div></div>
    <?php if (!$daily): ?><div class="empty-state">Tidak ada transaksi atau biaya pada rentang tanggal ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Omzet</th><th>HPP</th><th>Laba kotor</th><th>Biaya</th><th>Laba bersih</th><th>Margin kotor</th></tr></thead><tbody><?php foreach ($daily as $day): $dailyMargin = (float) $day['revenue'] > 0 ? (float) $day['gross_profit'] / (float) $day['revenue'] * 100 : 0; ?><tr><td class="strong"><?= e(format_date($day['day'])) ?></td><td><?= (int) $day['transactions'] ?></td><td><?= rupiah($day['revenue']) ?></td><td><?= rupiah($day['cogs']) ?></td><td class="<?= (float) $day['gross_profit'] < 0 ? 'margin-danger' : 'margin-good' ?>"><?= rupiah($day['gross_profit']) ?></td><td><?= rupiah($day['expenses']) ?></td><td class="<?= (float) $day['net_profit'] < 0 ? 'margin-danger' : 'margin-good' ?>"><?= rupiah($day['net_profit']) ?></td><td><?= number_format($dailyMargin, 1, ',', '.') ?>%</td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<div class="two-column">
    <section class="panel"><div class="panel-heading"><div><h3>Produk terlaris</h3><p>Urut berdasarkan omzet produk.</p></div></div>
        <?php if (!$top_products): ?><div class="empty-compact">Belum ada produk terjual dalam periode ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Terjual</th><th>Omzet</th><th>Laba</th></tr></thead><tbody><?php foreach ($top_products as $item): ?><tr><td class="strong"><?= e($item['product_name']) ?></td><td><?= e($item['quantity']) ?></td><td><?= rupiah($item['revenue']) ?></td><td class="<?= (float) $item['gross_profit'] < 0 ? 'margin-danger' : 'margin-good' ?>"><?= rupiah($item['gross_profit']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </section>
    <section class="panel"><div class="panel-heading"><div><h3>Riwayat pembelian</h3><p>Status pembelian dalam periode terpilih.</p></div></div>
        <?php if (!$purchases): ?><div class="empty-compact">Tidak ada pembelian pada periode ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Supplier</th><th>Nilai</th><th>Status</th></tr></thead><tbody><?php foreach ($purchases as $purchase): ?><tr><td><?= e(format_date($purchase['purchased_at'])) ?></td><td><?= e($purchase['supplier']) ?></td><td><?= rupiah($purchase['total']) ?></td><td><span class="badge <?= $purchase['status'] === 'confirmed' ? 'badge-green' : 'badge-gray' ?>"><?= e(ucfirst($purchase['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </section>
</div>
<section class="panel table-panel"><div class="panel-heading"><div><h3>Rincian biaya operasional</h3><p>Biaya yang dibatalkan tetap terlihat untuk menjaga histori, tetapi tidak dihitung sebagai biaya aktif.</p></div><a class="text-link" href="?page=expenses">Kelola biaya →</a></div>
    <?php if (!$expenses): ?><div class="empty-compact">Tidak ada biaya operasional pada periode ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th>Metode</th><th>Dicatat oleh</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><?php foreach ($expenses as $expense): ?><tr><td><?= e(format_date($expense['expense_date'])) ?></td><td><?= e($expense['category']) ?></td><td class="strong"><?= e($expense['description']) ?></td><td><?= e(strtoupper($expense['payment_method'])) ?></td><td><?= e($expense['created_by']) ?></td><td><?= rupiah($expense['amount']) ?></td><td><span class="badge <?= $expense['status'] === 'recorded' ? 'badge-green' : 'badge-gray' ?>"><?= $expense['status'] === 'recorded' ? 'Aktif' : 'Dibatalkan' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
